        public static void Export(ExportDataSelection selection)
        {
            try
            {
                var modelSelection = FinalFigureModelPresentation.Selection;
                var datas = GetExportData(selection).Where(d => d != null).ToList();
                if (datas.Count == 0)
                {
                    AppEventHandler.DisplayHandledException(new HandledException(
                        HandledException.Severity.Warning,
                        "No Figures Selected",
                        "No final figures matched the current export selection."));
                    return;
                }

                if (selection == ExportDataSelection.SelectedData)
                {
                    ExportSingleFigure(datas[0], modelSelection);
                    return;
                }

                var projectFolderName = GetProjectFolderName();
                var dlg = new NSOpenPanel();
                dlg.Title = "Export Figures";
                dlg.Message = $"Choose a parent folder. Figures will be exported to {projectFolderName}/.";
                dlg.Prompt = "Export";
                dlg.CanChooseDirectories = true;
                dlg.CanCreateDirectories = true;
                dlg.CanChooseFiles = false;


                dlg.BeginSheet(NSApplication.SharedApplication.MainWindow, (result) =>
                {
                    try
                    {
                        if (result != (int)NSModalResponse.OK) return;
                        var parentFolderPath = dlg.Url?.Path;
                        if (string.IsNullOrWhiteSpace(parentFolderPath)) return;

                        var projectFolderPath = Path.Combine(parentFolderPath, projectFolderName);
                        var targets = FigureExportPlanner.CreateTargets(datas, projectFolderPath);
                        var outcome = RunFigureBatchAfterConfirmation(targets, modelSelection, "Final figures",
                            approved => ConfirmOverwriteIfNeeded(NSApplication.SharedApplication.MainWindow, approved),
                            () => Directory.CreateDirectory(projectFolderPath));
                        if (outcome == null || !outcome.IsSuccess) return;

                        StatusBarManager.SetStatus(
                            $"{outcome.CompletedCount} final figure{(outcome.CompletedCount == 1 ? "" : "s")} exported to {Path.GetFileName(projectFolderPath)}",
                            3000);
                    }
                    catch (Exception error)
                    {
                        ReportFinalFigureBoundaryFailure(error);
                    }
                });
            }
            catch (Exception error)
            {
                ReportFinalFigureBoundaryFailure(error);
            }
        }

        static void ExportSingleFigure(ExperimentData data, PublicationFigureModelSelection selection)
        {
            var owner = CurrentFigureOwner(data);
            var ownerSolution = CurrentFigureSolution(data, owner);
            var panel = NSSavePanel.SavePanel;
            panel.Title = "Export Final Figure";
            panel.NameFieldStringValue = SanitizeFileName(data.Name) + ".pdf";
            panel.AllowedFileTypes = new[] { "pdf" };
            panel.CanCreateDirectories = true;

            try
            {
                panel.BeginSheet(NSApplication.SharedApplication.MainWindow, result =>
                {
                    try
                    {
                        if (result != (int)NSModalResponse.OK) return;

                        var selectedPath = panel.Url?.Path;
                        if (string.IsNullOrWhiteSpace(selectedPath)) return;
                        var path = selectedPath.EndsWith(".pdf", StringComparison.OrdinalIgnoreCase)
                            ? selectedPath
                            : selectedPath + ".pdf";

                        var approved = ExportBatchWriter.CaptureExistingPaths(new[] { path });
                        if (!string.Equals(path, selectedPath, StringComparison.Ordinal) && approved.Count > 0
                            && !ConfirmOverwriteIfNeeded(NSApplication.SharedApplication.MainWindow, approved)) return;
                        var outcome = ExportBatchWriter.Write(new[] { path }, approved,
                            (_, stream) => WriteFigurePdf(data, stream, owner, ownerSolution, selection));
                        if (!outcome.IsSuccess)
                        {
                            ExportFailurePresentation.Report("Final figure", outcome);
                            return;
                        }
                        StatusBarManager.SetStatus("Final figure exported", 3000);
                    }
                    catch (Exception error) { ReportFinalFigureBoundaryFailure(error); }
                });
            }
            catch (Exception error) { ReportFinalFigureBoundaryFailure(error); }
        }

        public static void Export(AnalysisResult result)
        {
            try { ExportAssociatedResult(result); }
            catch (Exception error) { ReportFinalFigureBoundaryFailure(error); }
        }

        static void ExportAssociatedResult(AnalysisResult result)
        {
            var modelSelection = FinalFigureModelPresentation.Selection;
            if (result == null)
            {
                AppEventHandler.DisplayHandledException(new HandledException(
                    HandledException.Severity.Warning,
                    "No Analysis Result Selected",
                    "Select an analysis result before exporting associated final figures."));
                return;
            }

            var validityReport = result.ValidityReport;
            if (!validityReport.IsValid)
            {
                var reasons = validityReport.Reasons ?? new List<string>();
                var reason = reasons.Count > 0
                    ? string.Join(Environment.NewLine, reasons)
                    : "The analysis result does not match the current experiment data.";

                AppEventHandler.DisplayHandledException(new HandledException(
                    HandledException.Severity.Warning,
                    "Invalid Analysis Result",
                    "Associated final figures can only be exported for analysis results that are valid for the current data."
                    + Environment.NewLine + Environment.NewLine + reason));
                return;
            }

            var datas = result.Solution?.Solutions?
                .Where(solution => solution?.Data != null)
                .Select(solution => solution.Data)
                .ToList() ?? new List<ExperimentData>();

            if (datas.Count == 0)
            {
                AppEventHandler.DisplayHandledException(new HandledException(
                    HandledException.Severity.Warning,
                    "No Figures Selected",
                    "The selected analysis result does not contain any experiments to export."));
                return;
            }

            var savedMembers = result.Solution?.Solutions?.ToList() ?? new List<SolutionInterface>();

            var dlg = new NSOpenPanel();
            dlg.Title = "Export Analysis Result Figures";
            dlg.Message = "Choose the parent folder for the exported PDF figures.";
            dlg.Prompt = "Export";
            dlg.CanChooseDirectories = true;
            dlg.CanCreateDirectories = true;
            dlg.CanChooseFiles = false;

            try
            {
                dlg.BeginSheet(NSApplication.SharedApplication.MainWindow, (modalResult) =>
                {
                    try
                    {
                        if (modalResult != (int)NSModalResponse.OK) return;

                        var parentFolderPath = dlg.Url?.Path;
                        if (string.IsNullOrWhiteSpace(parentFolderPath)) return;

                        var resultFolderPath = Path.Combine(parentFolderPath, FigureExportPlanner.SanitizeFileName(result.Name) ?? "Untitled Figure");
                        var exportTargets = FigureExportPlanner.CreateTargets(datas, resultFolderPath);
                        var paths = exportTargets.Select(target => target.Path).ToList();
                        var approved = ExportBatchWriter.CaptureExistingPaths(paths);

                        if (!ConfirmOverwriteIfNeeded(NSApplication.SharedApplication.MainWindow, approved)) return;

                        var outcome = WriteAssociatedFigureBatch(exportTargets, approved, result, savedMembers, modelSelection,
                            () => Directory.CreateDirectory(resultFolderPath));
                        if (!outcome.IsSuccess)
                        {
                            ExportFailurePresentation.Report("Analysis result figures", outcome);
                            return;
                        }

                        StatusBarManager.SetStatus("Analysis result figures exported", 3000);
                    }
                    catch (Exception error) { ReportFinalFigureBoundaryFailure(error); }
                });
            }
            catch (Exception error) { ReportFinalFigureBoundaryFailure(error); }
        }

        internal static ExportOutcome WriteFigureBatch(IReadOnlyList<FigureExportTarget> targets,
            ISet<string> approvedReplacementPaths, PublicationFigureModelSelection selection, Action prepare = null)
        {
            if (targets == null) throw new ArgumentNullException(nameof(targets));
            var paths = targets.Select(target => target.Path).ToList();
            return ExportBatchWriter.Write(paths, approvedReplacementPaths,
                (index, stream) => WriteFigurePdf(targets[index].Experiment, stream, selection: selection), prepare);
        }

        internal static ExportOutcome RunFigureBatchAfterConfirmation(
            IReadOnlyList<FigureExportTarget> targets,
            PublicationFigureModelSelection selection,
            string outputDescription,
            Func<ISet<string>, bool> confirm,
            Action prepare = null)
        {
            if (targets == null) throw new ArgumentNullException(nameof(targets));
            var paths = targets.Select(target => target.Path).ToList();
            var approved = ExportBatchWriter.CaptureExistingPaths(paths);
            if (approved.Count > 0 && (confirm == null || !confirm(approved))) return null;

            var outcome = WriteFigureBatch(targets, approved, selection, prepare);
            if (!outcome.IsSuccess) ExportFailurePresentation.Report(outputDescription, outcome);
            return outcome;
        }

        internal static ExportOutcome WriteAssociatedFigureBatch(IReadOnlyList<FigureExportTarget> targets,
            ISet<string> approvedReplacementPaths, AnalysisResult result,
            IReadOnlyList<SolutionInterface> savedMembers,
            PublicationFigureModelSelection selection, Action prepare = null)
        {
            if (targets == null) throw new ArgumentNullException(nameof(targets));
            if (result == null) throw new ArgumentNullException(nameof(result));
            var members = savedMembers ?? throw new ArgumentNullException(nameof(savedMembers));
            var paths = targets.Select(target => target.Path).ToList();
            return ExportBatchWriter.Write(paths, approvedReplacementPaths, (index, stream) =>
            {
                var target = targets[index];
                var solution = members.FirstOrDefault(candidate => ReferenceEquals(candidate?.Data, target.Experiment));
                if (solution?.Model == null)
                    throw new InvalidOperationException($"No fitted model is available for {target.Experiment.Name} in this analysis result.");
                WriteFigurePdf(target.Experiment, stream, result, solution, selection);
            }, prepare);
        }

        internal static string GetProjectFolderName()
        {
            var projectPath = FTITCFormat.CurrentAccessedAppDocumentPath;
            return FigureExportPlanner.GetProjectFolderName(projectPath, DateTime.Now);
        }

        internal static void WriteFigurePdf(ExperimentData data, string outputPath,
            AnalysisResult owner = null, SolutionInterface ownerSolution = null,
            PublicationFigureModelSelection? selection = null)
        {
            using (var pdfData = CreateFigurePdfData(data, owner, ownerSolution, selection))
                File.WriteAllBytes(outputPath, pdfData.ToArray());
        }

        internal static void WriteFigurePdf(ExperimentData data, Stream output,
            AnalysisResult owner = null, SolutionInterface ownerSolution = null,
            PublicationFigureModelSelection? selection = null)
        {
            if (output == null) throw new ArgumentNullException(nameof(output));
            using (var pdfData = CreateFigurePdfData(data, owner, ownerSolution, selection))
            {
                if (pdfData.Length == 0) throw new InvalidOperationException("The native PDF renderer produced no data.");
                var bytes = pdfData.ToArray();
                output.Write(bytes, 0, bytes.Length);
            }
        }

        static NSData CreateFigurePdfData(ExperimentData data, AnalysisResult owner,
            SolutionInterface ownerSolution, PublicationFigureModelSelection? selection)
        {
            var g = CreateFigure(data, null, owner, ownerSolution,
                selection ?? FinalFigureModelPresentation.Selection, out var model);
            var parameters = BuildPdfMetadataKeywords(data, model);
            var pdfInfo = new CGPDFInfo
            {
                Title = data.Name,
                Author = MarkdownStrings.AppName,
                Creator = $"{MarkdownStrings.AppName} v{AppVersion.FullVersionString}",
                Subject = $"ITC publication figure",
                Keywords = parameters.ToArray(),
            };

            var dataBuffer = new NSMutableData();
            try
            {
                using (var consumer = new CGDataConsumer(dataBuffer))
                using (var context = new CGContextPDF(consumer, pdfInfo))
                {
                    if (consumer.Handle == IntPtr.Zero || context.Handle == IntPtr.Zero)
                        throw new InvalidOperationException("Could not create the native PDF renderer.");
                    var printBox = g.PrintBox;
                    var pdfSize = new CGSize(printBox.Width * FinalFigurePdfScale, printBox.Height * FinalFigurePdfScale);
                    context.BeginPage(new CGRect(CGPoint.Empty, pdfSize));
                    context.SaveState();
                    context.ScaleCTM(FinalFigurePdfScale, FinalFigurePdfScale);
                    g.Draw(context, new CGPoint(printBox.Width / 2, printBox.Height / 2));
                    context.RestoreState();
                    context.EndPage();
                    context.Close();
                }
                if (dataBuffer.Length == 0)
                    throw new InvalidOperationException("The native PDF renderer produced no data.");
                return dataBuffer;
            }
            catch
            {
                dataBuffer.Dispose();
                throw;
            }
        }

        static string SanitizeFileName(string name)
            => FigureExportPlanner.SanitizeFileName(name) ?? "Untitled Figure";

        static bool ConfirmOverwriteIfNeeded(NSWindow parent, IEnumerable<string> outputPaths)
        {
            return ConfirmOverwriteIfNeeded(parent, ExportBatchWriter.CaptureExistingPaths(outputPaths));
        }

        static bool ConfirmOverwriteIfNeeded(NSWindow parent, ISet<string> existingPaths)
            => ConfirmOverwriteIfNeeded(parent, existingPaths, (alert, window) =>
                parent != null ? (IntPtr)(long)alert.RunSheetModal(parent) : (IntPtr)(long)alert.RunModal());

        internal static bool ConfirmOverwriteIfNeeded(NSWindow parent, ISet<string> existingPaths,
            Func<NSAlert, NSWindow, IntPtr> showModal)
        {
            var existing = (existingPaths ?? new HashSet<string>()).ToList();
            if (existing.Count == 0) return true;
            if (showModal == null) throw new ArgumentNullException(nameof(showModal));

            var alert = new NSAlert
            {
                AlertStyle = NSAlertStyle.Warning,
                MessageText = "File already exists.",
                InformativeText = existing.Count == 1
                    ? $"This export will overwrite:\n{Path.GetFileName(existing[0])}"
                    : $"This export will overwrite {existing.Count} files."
            };

            alert.AddButton("Overwrite");
            alert.AddButton("Cancel");
            return showModal(alert, parent) == (IntPtr)(long)NSAlertButtonReturn.First;
        }

        static void ReportFinalFigureBoundaryFailure(Exception error)
        {
            ExportFailurePresentation.Report("Final figures",
                ExportOutcome.Failure(0, error ?? new InvalidOperationException("An unknown export error occurred.")));
        }

        static IEnumerable<ExperimentData> GetExportData(ExportDataSelection selection)
        {
            switch (selection)
            {
                default:
                case ExportDataSelection.SelectedData:
                    return new[] { CurrentFigureData };
                case ExportDataSelection.IncludedData:
                    return DataManager.IncludedData;
                case ExportDataSelection.AllData:
                    return DataManager.Data;
            }
        }

        internal static int GetExportFigureCount(ExportDataSelection selection) =>
            GetExportData(selection).Count(data => data != null);

        static ExperimentData CurrentFigureData
        {
            get
            {
                if (DataManager.SelectedSolutionExperimentHighlight != null)
                {
                    return DataManager.SelectedSolutionExperimentHighlight;
                }

                if (DataManager.SelectedIsData
                    && DataManager.SelectedContentIndex >= 0
                    && DataManager.SelectedContentIndex < DataManager.SourceItems.Count
                    && DataManager.SourceItems[DataManager.SelectedContentIndex] is ExperimentData selectedData)
                {
                    return selectedData;
                }

                return DataManager.Current;
            }
        }

        static EnergyUnit ResolveEnergyUnit(ExperimentData data, PublicationFigureModelResolution model)
            => EnergyUnitResolver.Resolve(
                FinalFigureModelPresentation.EnergyUnitFamily,
                MacEnergyUnitPresentation.MolarEnergyValues(
                    data,
                    model?.Solution,
                    DrawFitOffsetCorrected && model?.IsNull != true,
                    ShowResiduals,
                    DrawFitParameters
                        ? VisibleFinalFigureDisplayParameters
                        : FinalFigureDisplayParameters.None));

        static AnalysisResult CurrentFigureOwner(ExperimentData data)
        {
            if (data == null || DataManager.SelectedSolutionExperimentHighlight == null
                || !ReferenceEquals(DataManager.SelectedSolutionExperimentHighlight, data)) return null;
            return DataManager.SelectedResult;
        }

        static SolutionInterface CurrentFigureSolution(ExperimentData data, AnalysisResult owner = null)
            => (owner ?? CurrentFigureOwner(data))?.Solution?.Solutions?.FirstOrDefault(solution =>
                solution?.Data != null && ReferenceEquals(solution.Data, data));

        internal static string CurrentAssessmentText => CurrentFigureData == null
            ? FinalFigureModelPresentation.NoAssessmentText
            : FinalFigureModelPresentation.AssessmentText(new PublicationFigureSource(CurrentFigureData,
                CurrentFigureSolution(CurrentFigureData) ?? CurrentFigureData.Solution, CurrentFigureOwner(CurrentFigureData)));

        /// <summary>Displayed fit: the exact result member or attached fit and its saved comparison; never fits.</summary>
        internal static PublicationFigureModelResolution ResolveFigure(ExperimentData data, AnalysisResult owner,
            SolutionInterface member, PublicationFigureModelSelection selection)
            => PublicationFigureBuilder.ResolveModel(new PublicationFigureSource(data,
                owner == null ? data.Solution : member, owner, modelSelection: selection));

        /// <summary>Unified axes resolve each other experiment from its own result member or attached fit.</summary>
        static Func<ExperimentData, SolutionInterface> SolutionResolver(AnalysisResult owner, PublicationFigureModelSelection selection)
            => experiment =>
            {
                var owned = CurrentFigureSolution(experiment, owner);
                return ResolveFigure(experiment, owned == null ? null : owner, owned, selection).Solution;
            };

        static string[] BuildPdfMetadataKeywords(ExperimentData data, PublicationFigureModelResolution model)
        {
            using var numericCulture = new InvariantNumericCultureScope();
            var solution = model?.Solution;
            var parameters = new List<string>()
            {
                $"Name: {data.Name}",
                $"File: {data.FileName}",
                $"File Date: {data.Date:yyyy-MM-dd}",
                $"[Syringe]: {data.SyringeConcentration.AsConcentration(ConcentrationUnit.µM, true)}",
                $"[Cell]: {data.CellConcentration.AsConcentration(ConcentrationUnit.µM, true)}",
                $"Model: {GetModelMetadata(model)}",
                $"Solution: {GetSolutionScope(solution)}",
                $"Loss: {GetLossMetadata(solution)}"
            };

            if (solution == null) return parameters.Select(p => p.Replace(",", "..")).ToArray();

            var reportParameters = solution.ReportParameters ?? new Dictionary<ParameterType, FloatWithError>();
            var ordered = new List<KeyValuePair<ParameterType, FloatWithError>>();

            foreach (var key in PdfMetadataParameterOrder)
            {
                if (reportParameters.ContainsKey(key))
                {
                    ordered.Add(new KeyValuePair<ParameterType, FloatWithError>(key, reportParameters[key]));
                    continue;
                }

                if (solution.Parameters.ContainsKey(key))
                {
                    ordered.Add(new KeyValuePair<ParameterType, FloatWithError>(key, solution.Parameters[key]));
                }
            }

            foreach (var par in ordered)
            {
                parameters.Add($"{GetParameterMetadataLabel(par.Key)} = {FormatParameterMetadataValue(data, model, par.Key, par.Value)}");
            }

            return parameters.Select(p => p.Replace(",", "..")).ToArray();
        }

        static string GetModelMetadata(PublicationFigureModelResolution model)
        {
            if (model?.IsNull == true) return model.ModelLabel;
            var solution = model?.Solution;
            if (solution == null) return "";

            return solution.ModelType.GetProperties()?.Name ?? solution.ModelType.ToString();
        }

        static string GetSolutionScope(SolutionInterface solution)
        {
            if (solution == null) return "";

            return solution.IsGlobalAnalysisSolution ? "Global" : "Single";
        }

        static string GetLossMetadata(SolutionInterface solution)
        {
            if (solution == null) return "";

            return solution.UnweightedRmsd.ToString("G3");
        }

        static string GetParameterMetadataLabel(ParameterType key)
        {
            if (ThermodynamicParameterSlots.TryResolve(key, out var slot, out var family))
            {
                var suffix = slot.Index == 1 ? string.Empty : slot.Index.ToString();
                return family switch
                {
                    ThermodynamicParameterFamily.Affinity => "Kd" + suffix,
                    ThermodynamicParameterFamily.Enthalpy => "ΔH" + suffix,
                    ThermodynamicParameterFamily.EntropyContribution => "-TΔS" + suffix,
                    ThermodynamicParameterFamily.Gibbs => "ΔG" + suffix,
                    ThermodynamicParameterFamily.HeatCapacity => "ΔCp" + suffix,
                    ThermodynamicParameterFamily.Entropy => "ΔS" + suffix,
                    _ => key.GetProperties().Name,
                };
            }

            return key switch
            {
                ParameterType.Nvalue1 => "N",
                ParameterType.Nvalue2 => "N2",
                ParameterType.ApparentAffinity => "Kd app",
                ParameterType.IsomerizationEquilibriumConstant => "Keq",
                ParameterType.IsomerizationRate => "kiso",
                ParameterType.CisIsomerPopulationPercentage => "%cis",
                _ => key.GetProperties().Name
            };
        }

        static string FormatParameterMetadataValue(ExperimentData data, PublicationFigureModelResolution model,
            ParameterType key, FloatWithError value)
        {
            var parent = key.GetProperties().ParentType;
            var energyUnit = ResolveMetadataEnergyUnit(data, model, key);
            var uncertaintyStyle = UncertaintyDisplayStyle.StandardDeviationAndConfidenceInterval;

            return parent switch
            {
                ParameterType.Affinity1 => value.AsFormattedConcentration(withunit: true, style: uncertaintyStyle),
                ParameterType.Enthalpy1 => value.Energy.ToFormattedString(energyUnit, permole: true, style: uncertaintyStyle),
                ParameterType.EntropyContribution1 => value.Energy.ToFormattedString(energyUnit, permole: true, style: uncertaintyStyle),
                ParameterType.Gibbs1 => value.Energy.ToFormattedString(energyUnit, permole: true, style: uncertaintyStyle),
                ParameterType.Offset => value.Energy.ToFormattedString(energyUnit, permole: true, style: uncertaintyStyle),
                ParameterType.HeatCapacity1 => value.Energy.ToFormattedString(energyUnit, permole: true, perK: true, style: uncertaintyStyle),
                _ => value.AsNumber(uncertaintyStyle),
            };
        }

        static EnergyUnit ResolveMetadataEnergyUnit(ExperimentData data, PublicationFigureModelResolution model, ParameterType key)
        {
            if (key.GetProperties().ParentType != ParameterType.HeatCapacity1)
                return ResolveEnergyUnit(data, model);

            var values = model?.Solution?.ReportParameters?
                .Where(parameter => parameter.Key.GetProperties().ParentType == ParameterType.HeatCapacity1)
                .Select(parameter => parameter.Value.Value);
            return EnergyUnitResolver.Resolve(FinalFigureModelPresentation.EnergyUnitFamily, values);
        }

        void InitializeGraph()
        {
            if (StateManager.CurrentState != ProgramState.Publish) return;
            var data = CurrentFigureData;
            if (data == null) return;

            var owner = CurrentFigureOwner(data);
            graph = CreateFigure(data, this, owner, CurrentFigureSolution(data, owner),
                FinalFigureModelPresentation.Selection, out _);

            SetFrameSize(graph.PrintBox.Size); 

            PlotSizeChanged?.Invoke(graph, null);
        }

        public void Export()
        {
            Export(ExportDataSelection.SelectedData);
        }

        public override void DrawRect(CGRect dirtyRect)
        {
            if (StateManager.CurrentState != ProgramState.Publish) return;
            if (CurrentFigureData == null) return;
            if (graph == null) { InitializeGraph(); }

            base.DrawRect(dirtyRect);

            var cg = NSGraphicsContext.CurrentContext.CGContext;

            if (graph == null) return;

            graph.Draw(cg, new CGPoint(Frame.Width / 2, Frame.Height / 2));
        }

        public void Print()
        {
            var scalingfactor = 1 / 1.576f;

            var op = NSPrintOperation.FromView(this);
            op.PrintInfo.PaperSize = this.Frame.Size.ScaleBy(scalingfactor);
            op.PrintInfo.BottomMargin = 0;
            op.PrintInfo.TopMargin = 0;
            op.PrintInfo.LeftMargin = 0;
            op.PrintInfo.RightMargin = 0;
            op.PrintInfo.ScalingFactor = scalingfactor;
            op.RunOperation();
        }

        void UnsubscribeEvents()
        {
            if (eventsUnsubscribed) return;
            eventsUnsubscribed = true;

            DataManager.SelectionDidChange -= DataManager_SelectionDidChange;
            DataManager.ResultLinkedExperimentHighlightDidChange -= DataManager_SelectionDidChange;
            if (subscribedFigureResult != null)
                subscribedFigureResult.BindingAssessmentChanged -= FigureAssessmentChanged;
            subscribedFigureResult = null;
            Invalidated -= FinalFigureGraphView_Invalidated;
            AppSettings.SettingsDidUpdate -= FinalFigureGraphView_Invalidated;
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing) UnsubscribeEvents();

            base.Dispose(disposing);
        }
    }
}
